import {Globe} from './globe.js';
import {MIN_YEAR,MAX_YEAR,epochs,formatYear,activeAt,yearToPosition,positionToYear,parseYear,matches,activeRelations} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const regionColors={Африка:'#d8bd7c',Европа:'#a4c5b5',Азия:'#c7db9b',Америка:'#dca991',Океания:'#a8c4cf'};
const modeNames={cultures:'Культуры и общества',religions:'Религии и верования',relations:'Торговля и отношения'};
let data,globe,timer=null,year=-2560,mode='cultures',selected='egypt-old',q='',region='all',relationType='all',panel=null,returnFocus=null,detailKey='';
const period=c=>`${c.approximate?'ок. ':''}${formatYear(c.start)} — ${formatYear(c.end)}`;
const sourceLinks=ids=>[...new Set(ids)].map(id=>{const s=data.sources[id];return s?`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`:'';}).join('');
const color=c=>mode==='religions'?(data.religions[c.religions[0]]?.color||'#c0b68e'):regionColors[c.region]||'#c4d28a';
const current=()=>activeAt(data.cultures,year);
const visible=()=>current().filter(c=>(region==='all'||c.region===region)&&(!q||matches(c,q)));
const links=()=>activeRelations(data,year,relationType);
const chooseCurrent=()=>[...current()].sort((a,b)=>(a.end-a.start)-(b.end-b.start))[0]?.id||null;
function persist(){const p=new URLSearchParams({year:String(year),mode,culture:selected||''});history.replaceState(null,'','#'+p);try{localStorage.setItem('chronos-state-v1',JSON.stringify({year,mode,selected}));}catch{}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function setPanel(name,focus=true){const previous=panel;if(name&&!previous)returnFocus=document.activeElement?.tagName==='BODY'?$('#globe'):document.activeElement;panel=name;$('#explorerPanel').hidden=name!=='explorer';$('#detailPanel').hidden=name!=='detail';$('#searchToggle').setAttribute('aria-expanded',String(name==='explorer'));globe?.setPanel(name);if(name){if(focus)requestAnimationFrame(()=>{if(panel===name)(name==='explorer'?$('#search'):$('#detailPanel [data-close-panel]')).focus({preventScroll:true});});}else if(previous&&focus){(returnFocus?.isConnected?returnFocus:$('#globe')).focus({preventScroll:true});}}
function setImmersive(active){document.body.classList.toggle('focus-mode',active);$('#exitFocus').hidden=!active;$('#focusMode').setAttribute('aria-pressed',String(active));$('#focusMode').setAttribute('aria-label',active?'Выключить режим погружения':'Включить режим погружения');if(active){setPanel(null,false);toggleYear(false);toggleLegend(false);$('#globe').focus({preventScroll:true});}else $('#focusMode').focus({preventScroll:true});}
function selectCulture(id,focus=true){const c=data.cultures.find(c=>c.id===id);if(!c)return;stop();setSpin(false);selected=id;if(year<c.start||year>c.end){year=Math.max(c.start,Math.min(c.end,year));toast(`Переход: ${formatYear(year)}`);}if(document.body.classList.contains('focus-mode'))setImmersive(false);render();toggleYear(false);toggleLegend(false);setPanel('detail');if(focus)globe.focus(c.coordinates);}
function setYear(y){year=y;if(!current().some(c=>c.id===selected))selected=chooseCurrent();render();}
function setMode(m){mode=m;render();toast(modeNames[m]);}
function cultureRows(rows){const expanded=new Set($$('.region-group[open]').map(g=>g.dataset.region));const initial=!$('#cultureList').children.length;return Object.entries(regionColors).map(([r,col])=>{const cs=rows.filter(c=>c.region===r);if(!cs.length)return '';return `<details class="region-group" data-region="${r}" ${initial||expanded.has(r)||q?'open':''}><summary><span class="swatch" style="background:${col}"></span>${r}<span class="group-count">${cs.length}</span>${icon('chevron')}</summary><div>${cs.map(c=>`<button class="culture-row ${c.id===selected?'selected':''}" data-culture="${c.id}" aria-pressed="${c.id===selected}"><span><strong>${esc(c.name)}</strong><small>${c.start<=year&&year<=c.end?esc(c.kind):period(c)+' · перейти'}</small></span><span class="row-arrow">${icon('arrow')}</span></button>`).join('')}</div></details>`;}).join('');}
function render(){const list=visible(),allCurrent=current();if(selected&&!allCurrent.some(c=>c.id===selected))selected=null;
 $('#worldDate').innerHTML=`${Math.abs(year).toLocaleString('ru-RU')} <small>${year<0?'до н. э.':'н. э.'}</small>`;$('#dateJump').setAttribute('aria-label',`${formatYear(year)}. Выбрать другой год`);
 let epoch=epochs[0];for(const e of epochs)if(year>=e.start)epoch=e;$('#epochLabel').textContent=epoch.name.toUpperCase();$('#dockEpoch').textContent=epoch.name;
 const pos=yearToPosition(year);$('#timeRange').value=pos;$('#timeRange').style.setProperty('--progress',`${pos/10}%`);$('#timeRange').setAttribute('aria-valuetext',formatYear(year));$('#yearInput').value=Math.abs(year);$('#era').value=year<0?'bce':'ce';$('#relationType').hidden=mode!=='relations';
 $('#activeCount').textContent=`${list.length} ${list.length===1?'место':'мест'}`;$('#modeCaption').textContent=modeNames[mode];
 $$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode);});
 const rows=q?data.cultures.filter(c=>matches(c,q)&&(region==='all'||c.region===region)):list;$('#count').textContent=rows.length;$('#listCaption').textContent=q?'РЕЗУЛЬТАТЫ ВО ВСЕХ ЭПОХАХ':'В ВЫБРАННОМ ГОДУ';
 $('#cultureList').innerHTML=rows.length?cultureRows(rows):`<div class="empty">${q?'Пока не нашли такую историю. Попробуйте другое название.':'Для этого времени и региона записи ещё не добавлены.'}<button id="clearFilters">Сбросить фильтры</button></div>`;
 const displayed=mode==='relations'?list.filter(c=>links().some(r=>r.from===c.id||r.to===c.id)):list;
 globe.setData(displayed,links(),mode,selected,color);
 if(mode==='religions'){const rels=[...new Set(list.flatMap(c=>c.religions))];$('#legend').innerHTML=rels.map(id=>`<span><i style="background:${data.religions[id].color}"></i>${esc(data.religions[id].name)}</span>`).join('');}else if(mode==='relations')$('#legend').innerHTML='<span><i style="background:#e3eaa4"></i>Торговля и обмен →</span><span><i style="background:#edac83"></i>Колониальная зависимость ⇢</span>';else $('#legend').innerHTML=Object.entries(regionColors).filter(([r])=>list.some(c=>c.region===r)).map(([r,col])=>`<span><i style="background:${col}"></i>${r}</span>`).join('');
 const c=list.find(c=>c.id===selected)||list[0];$('#sceneKicker').textContent=mode==='relations'?'МИР, СОЕДИНЁННЫЙ СВЯЗЯМИ':mode==='religions'?'КАК ЧЕЛОВЕК ОБЪЯСНЯЛ МИР':'СЛЕДЫ ОДНОЙ ЭПОХИ';$('#sceneCaption').textContent=c?c.name:'История здесь ещё ждёт своего исследователя.';$('#discover').dataset.culture=c?.id||'';$('#discover').disabled=!c;
 renderDetail();persist();
}
function chapter(id,title,ico,body,open=false){return `<details class="chapter" data-chapter="${id}" ${open?'open':''}><summary>${icon(ico)}<span>${esc(title)}</span>${icon('chevron','chevron')}</summary><div class="chapter-body">${body}</div></details>`;}
function renderDetail(){const c=data.cultures.find(c=>c.id===selected);const key=selected+':'+mode;const open=detailKey===key?new Set($$('#detail details[open]').map(d=>d.dataset.chapter)):new Set();detailKey=key;
 if(!c){$('#detail').innerHTML=`<div class="detail-top">НЕИССЛЕДОВАННЫЙ УЧАСТОК</div><h2>История ещё не добавлена</h2><p class="summary">В выбранном году база пока не содержит записей. Здесь тоже жили люди — нам ещё предстоит рассказать об их мире.</p><button class="primary" data-story="pyramids">Начать с эпохи пирамид ${icon('arrow')}</button><button class="secondary" data-about>О покрытии базы</button>`;return;}
 let content='';if(mode==='cultures'){
  const rulers=c.rulers.filter(r=>r.start<=year&&year<=r.end),events=[...c.events].filter(e=>e.year<=year).sort((a,b)=>b.year-a.year);
  content=`<p class="summary">${esc(c.summary)}</p>`;
  content+=chapter('society','Как было устроено общество','cultures',`<dl><dt>Власть</dt><dd>${esc(c.government)}</dd><dt>Люди и повседневность</dt><dd>${esc(c.society)}</dd><dt>Правитель в ${formatYear(year)}</dt><dd>${rulers.length?rulers.map(r=>esc(r.name)).join(', '):'В проверенной базе пока не указан'}</dd></dl>`,open.has('society'));
  content+=chapter('economy','Чем жили и что производили','relations',`<p>${esc(c.economy)}</p>`,open.has('economy'));
  content+=chapter('beliefs','Во что верили','religions',c.religions.map(id=>`<p><strong style="color:${data.religions[id].color}">${esc(data.religions[id].name)}</strong><br>${esc(data.religions[id].summary)}</p>`).join(''),open.has('beliefs'));
  if(events.length)content+=chapter('events','События к выбранному году','time',events.map(e=>`<div class="event"><strong>${formatYear(e.year)}</strong><p>${esc(e.text)}</p></div>`).join(''),open.has('events'));
 }else if(mode==='religions'){
  content='<p class="summary">Как человек объяснял мир, смерть, власть и своё место среди других. Откройте традицию, чтобы прочитать её историю.</p>';
  content+=c.religions.map(id=>{const r=data.religions[id];return chapter('rel-'+id,r.name,'religions',`<p>${esc(r.summary)}</p><dl><dt>Формирование</dt><dd>${esc(r.origin)}</dd></dl>${sourceLinks(r.sources)}`,open.has('rel-'+id));}).join('');
  content+='<p class="uncertainty">Традиции могли сосуществовать. Цвет не обозначает долю верующих или однородность общества.</p>';
 }else{
  const rels=links().filter(r=>r.from===c.id||r.to===c.id);content='<p class="summary">Следуйте за вещами и людьми: что обменивали, кто получал выгоду, кому доставались издержки.</p>';
  content+=rels.length?rels.map(r=>chapter('link-'+r.id,r.title,'relations',`<span class="eyebrow">${r.type==='colonial'?'КОЛОНИАЛЬНАЯ ЗАВИСИМОСТЬ':'ТОРГОВЛЯ И ОБМЕН'}</span><dl><dt>Что отправляли</dt><dd>${esc(r.goods)}</dd><dt>Встречный поток и контроль</dt><dd>${esc(r.returns)}</dd><dt>Выгоды и издержки</dt><dd>${esc(r.impact)}</dd></dl>${sourceLinks(r.sources)}<div class="relation-card"><button data-culture="${r.from===c.id?r.to:r.from}">Открыть другую сторону ${icon('arrow')}</button></div>`,open.has('link-'+r.id))).join(''):'<p class="uncertainty">Проверенные связи для этого года и фильтра ещё не добавлены. Другие типы связей можно найти через поиск.</p>';
  if(relationType!=='all')content+='<button class="secondary" id="allRelations">Показать все типы связей</button>';
 }
 content+=chapter('sources','Источники и оговорки','book',`<p>${esc(c.note)}</p>${sourceLinks(c.sources)}`,open.has('sources'));
 $('#detail').innerHTML=`<div class="detail-top"><span>${esc(c.region.toUpperCase())}</span><span class="type-label">${esc(c.kind)}</span></div><h2>${esc(c.name)}</h2><div class="period">${period(c)}</div>${content}<button class="primary" id="compare">${icon('globe')}Сравнить с современниками ${icon('arrow')}</button>${c.id==='egypt-old'&&year>=-3000&&year<=-1800?'<button class="secondary" data-compare="caral">А что в это время в Америке?</button>':''}`;
}
function modal(html){stop();setSpin(false);toggleYear(false);toggleLegend(false);$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function about(){modal(`<h2>История без иллюзии полноты.</h2><p>Хронос позволяет посмотреть на разные общества в один момент времени. Это первая исследовательская версия: база выборочная и не претендует на охват всех эпох, наций, правителей и религий.</p><div class="stat-grid"><span><strong>${data.cultures.length}</strong><small>исторических обзора</small></span><span><strong>${data.relations.length}</strong><small>связей</small></span><span><strong>${Object.keys(data.sources).length}</strong><small>источника</small></span></div><h3>Что именно показывает глобус</h3><p>Точки обозначают ориентировочные центры присутствия или места памятников. Это не исторические границы. Современная береговая линия взята из Natural Earth (общественное достояние). Ранние общества не отождествляются с современными нациями. Линии связей схематичны; некоторые обмены происходили через цепочки посредников.</p><h3>Как читать датировки</h3><p>Доисторические интервалы округлены. Диапазон карточки — рамки обзора, а не гарантия неизменности общества. Названия эпох — условная навигация: периодизация отличается по регионам. Шкала нелинейная: древним эпохам и недавним столетиям отведено сопоставимое место. Года 0 нет. Точный ввод поддерживается от 100 000 до н. э. до 2025 н. э.; точность выбора года не означает такую же точность реконструкции.</p><h3>Верования и власть</h3><p>Цвет означает выбранную в обзоре традицию, а не религиозную однородность или долю верующих. В карточках перечислены также сосуществующие традиции. «Реконструкция ограничена» означает недостаток данных для уверенного описания, а не отсутствие верований. Правители показаны только там, где есть датированные записи.</p><h3>Источники и развитие базы</h3><p>Краткие тексты — авторские обзоры по музейным, научным и институциональным материалам; они ещё не прошли независимое научное рецензирование. Африка, Америка и особенно Океания пока представлены неравномерно. Каждая запись хранит источники и примечания отдельно; дополнения и исправления можно предлагать в репозитории. Обновление базы: ${data.updated}.</p><div class="source-index">${sourceLinks(Object.keys(data.sources))}</div><p>География: Natural Earth, public domain. Визуализация: D3, ISC © Mike Bostock. Приложение не использует платные API. Шрифты Google Fonts загружаются при наличии сети; предусмотрены системные замены.</p>`);}
function showSources(){const c=data.cultures.find(c=>c.id===selected);if(!c)return;modal(`<h2>${esc(c.name)}<br>Источники и оговорки</h2><p>${esc(c.note)}</p><p>${period(c)}. Для точных событий и спорных интерпретаций сверяйтесь с первоисточниками. Карточка — краткий обзор, а не полная библиография.</p><div class="source-index">${sourceLinks(c.sources)}</div>`);}
function compare(aId=selected,bId){const cs=current(),a=cs.find(c=>c.id===aId)||cs[0],b=cs.find(c=>c.id===bId)||cs.find(c=>c.id!==a?.id);if(!a||!b){toast('Для сравнения нужны как минимум две записи в одном году.');return;}const opts=id=>cs.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('');modal(`<span class="eyebrow">ОДНОВРЕМЕННО НА ЗЕМЛЕ / ${formatYear(year)}</span><h2>Разные миры. Один год.</h2><div class="compare-chooser"><select id="compareA" aria-label="Первая культура">${opts(a.id)}</select><select id="compareB" aria-label="Вторая культура">${opts(b.id)}</select></div><div class="comparison">${[a,b].map(c=>`<article><h3>${esc(c.name)}</h3><span class="eyebrow">${esc(c.region)}</span><p>${esc(c.summary)}</p><span class="compare-label">УСТРОЙСТВО ОБЩЕСТВА</span><p>${esc(c.government)}. ${esc(c.society)}</p><span class="compare-label">ХОЗЯЙСТВО</span><p>${esc(c.economy)}</p><span class="compare-label">ВЕРОВАНИЯ</span><p>${c.religions.map(id=>esc(data.religions[id].name)).join(', ')}</p>${sourceLinks(c.sources)}<p>${esc(c.note)}</p></article>`).join('')}</div><p>Сосуществование во времени само по себе не доказывает контактов между обществами.</p>`);$('#compareA').onchange=()=>compare($('#compareA').value,$('#compareB').value);$('#compareB').onchange=()=>compare($('#compareA').value,$('#compareB').value);}
function journeys(){modal($('#journeyTemplate').innerHTML);}
function showEpochs(){let epoch=epochs[0];for(const e of epochs)if(year>=e.start)epoch=e;modal(`<span class="eyebrow">ВЫБЕРИТЕ ТОЧКУ ОТПРАВЛЕНИЯ</span><h2>У времени много глубин.</h2><p>Переходите от археологических эпох к конкретным годам. Периодизация условна и отличается в разных регионах.</p><div class="epoch-options">${epochs.map((e,i)=>`<button data-epoch="${e.year}" class="${epoch===e?'active':''}"><span class="epoch-index">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(e.name)}</strong><small>${formatYear(e.year)}</small></span></button>`).join('')}</div>`);}
function help(){modal(`<span class="eyebrow">НЕБОЛЬШОЙ КОМПАС ДЛЯ БОЛЬШОГО МИРА</span><h2>Исследуйте в своём ритме.</h2><div class="help-grid"><article class="help-item">${icon('globe')}<h3>Прикоснитесь к Земле</h3><p>Проведите одним пальцем, чтобы вращать планету. Разведите два пальца, чтобы приблизить. На компьютере используйте перетаскивание и колесо мыши.</p></article><article class="help-item">${icon('time')}<h3>Двигайтесь во времени</h3><p>Шкала внизу ведёт через эпохи. Нажмите на год, чтобы ввести свой, или на название эпохи, чтобы выбрать период. Кнопка воспроизведения запускает путешествие.</p></article><article class="help-item">${icon('cultures')}<h3>Следуйте за любопытством</h3><p>Нажмите на светящуюся точку или её название. Карточка открывается по запросу; разделы внутри раскрываются отдельно. В поиске культуры сгруппированы по частям света.</p></article><article class="help-item">${icon('compass')}<h3>Меняйте угол зрения</h3><p>Переключайте культуры, религии и связи. Путешествия предлагают готовые вопросы. Режим погружения скрывает управление; вернуть его можно кнопкой на экране или Escape.</p></article></div><p>Клавиатура: стрелки вращают глобус, + и − меняют масштаб. / открывает поиск, F — погружение, Escape — закрыть панель. Все действия также доступны кнопками.</p>`);}
function toggleYear(show){const active=typeof show==='boolean'?show:$('#yearPopover').hidden;$('#yearPopover').hidden=!active;$('#yearToggle').setAttribute('aria-expanded',String(active));if(active){toggleLegend(false);requestAnimationFrame(()=>{$('#yearInput').focus();$('#yearInput').select();});}}
function toggleLegend(show){const active=typeof show==='boolean'?show:$('#legendPanel').hidden;$('#legendPanel').hidden=!active;$('#legendToggle').setAttribute('aria-expanded',String(active));if(active){toggleYear(false);setPanel(null,false);}}
function clearFilters(){q='';region='all';relationType='all';$('#search').value='';$('#region').value='all';$('#relationType').value='all';render();}
function story(name){stop();clearFilters();$('#modal').close();setPanel(null,false);if(name==='pyramids'){year=-2560;mode='cultures';selected='egypt-old';render();globe.focus([31,20]);compare('egypt-old','caral');}else if(name==='novgorod'){year=1250;mode='relations';selected='novgorod';render();globe.focus([24,52]);setPanel('detail');toast('1250 год. Откройте связь с ганзейскими купцами.');}else{year=1600;mode='relations';selected='potosi';render();globe.focus([-40,-3]);setPanel('detail');toast('1600 год. Откройте историю серебра и колониального контроля.');}}
function stop(){clearInterval(timer);timer=null;$('#play').innerHTML=icon('play');$('#play').setAttribute('aria-label','Запустить путешествие во времени');$('#play').setAttribute('aria-pressed','false');}
function play(){if(timer){stop();return;}if(year>=MAX_YEAR)setYear(MIN_YEAR);$('#play').innerHTML=icon('pause');$('#play').setAttribute('aria-label','Остановить путешествие');$('#play').setAttribute('aria-pressed','true');timer=setInterval(()=>{const p=Math.min(1000,yearToPosition(year)+4);setYear(positionToYear(p));if(p>=1000)stop();},500);}
function setSpin(active){globe?.setSpinning(active);$('#autoRotate').setAttribute('aria-pressed',String(active));$('#autoRotate').setAttribute('aria-label',active?'Остановить плавное вращение':'Включить плавное вращение');}
function bind(){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.culture)selectCulture(b.dataset.culture);if(b.dataset.mode)setMode(b.dataset.mode);if(b.dataset.epoch){stop();$('#modal').close();setPanel(null,false);setYear(Number(b.dataset.epoch));const c=data.cultures.find(c=>c.id===selected);if(c)globe.focus(c.coordinates);$('#epochsToggle').focus({preventScroll:true});}if(b.dataset.story)story(b.dataset.story);if(b.dataset.compare)compare(selected,b.dataset.compare);if(b.hasAttribute('data-about'))about();if(b.hasAttribute('data-close-panel'))setPanel(null);if(b.hasAttribute('data-close-legend')){toggleLegend(false);$('#legendToggle').focus();}if(b.id==='clearFilters'||b.id==='resetFilters')clearFilters();if(b.id==='compare')compare();if(b.id==='selectedSources')showSources();if(b.id==='allRelations'){relationType='all';$('#relationType').value='all';render();}});
 $('#yearForm').addEventListener('submit',e=>{e.preventDefault();const y=parseYear($('#yearInput').value,$('#era').value);if(y===null){$('#yearError').textContent=`Введите целый год без нуля: от 100 000 до н. э. до ${MAX_YEAR} н. э.`;return;}$('#yearError').textContent='';stop();setYear(y);toggleYear(false);$('#dateJump').focus({preventScroll:true});});
 $('#timeRange').addEventListener('input',e=>{stop();$('#yearError').textContent='';setYear(positionToYear(Number(e.target.value)));});
 $('#search').oninput=e=>{q=e.target.value;render();};$('#region').onchange=e=>{region=e.target.value;render();};$('#relationType').onchange=e=>{relationType=e.target.value;render();};
 $('#searchToggle').onclick=()=>{toggleLegend(false);toggleYear(false);setPanel(panel==='explorer'?null:'explorer');};$('#legendToggle').onclick=()=>toggleLegend();$('#dateJump').onclick=()=>toggleYear();$('#yearToggle').onclick=()=>toggleYear();$('#closeYear').onclick=()=>{toggleYear(false);$('#yearToggle').focus();};$('#epochsToggle').onclick=showEpochs;
 $('#resetView').onclick=()=>{setSpin(false);globe.reset();};$('#zoomIn').onclick=()=>globe.setZoom(globe.zoom*1.2);$('#zoomOut').onclick=()=>globe.setZoom(globe.zoom/1.2);$('#autoRotate').onclick=()=>setSpin(!globe.spinning);$('#focusMode').onclick=()=>setImmersive(!document.body.classList.contains('focus-mode'));$('#exitFocus').onclick=()=>setImmersive(false);$('#play').onclick=play;
 document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();setSpin(false);}});
 ['aboutNav','coverageBtn','methodNav'].forEach(id=>$('#'+id).onclick=about);$('#help').onclick=help;$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});$('#storiesNav').onclick=journeys;$('#journeyToggle').onclick=journeys;$('#atlasNav').onclick=()=>{setPanel(null);toggleYear(false);toggleLegend(false);};
 document.addEventListener('keydown',e=>{const editing=e.target.closest('input,select,textarea,[contenteditable="true"]');if(e.key==='Escape'&&!$('#modal').open){if(!$('#yearPopover').hidden){toggleYear(false);$('#yearToggle').focus();}else if(!$('#legendPanel').hidden){toggleLegend(false);$('#legendToggle').focus();}else if(panel)setPanel(null);else if(document.body.classList.contains('focus-mode'))setImmersive(false);}if(editing||$('#modal').open||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='/'){e.preventDefault();if(document.body.classList.contains('focus-mode'))setImmersive(false);setPanel('explorer');}if(e.key.toLowerCase()==='f'){e.preventDefault();setImmersive(!document.body.classList.contains('focus-mode'));}});
 $('#share').onclick=async()=>{persist();try{await navigator.clipboard.writeText(location.href);toast('Ссылка на этот момент скопирована.');}catch{modal(`<h2>Пригласите в этот момент.</h2><p>Скопируйте адрес выбранного года и режима:</p><input aria-label="Ссылка" class="share-input" readonly value="${esc(location.href)}">`);}};
}
async function init(){try{const [d,l]=await Promise.all([fetch('data/history.json').then(r=>{if(!r.ok)throw Error('Историческая база недоступна');return r.json();}),fetch('data/land.geojson').then(r=>{if(!r.ok)throw Error('География недоступна');return r.json();})]);if(!window.d3)throw Error('Не удалось загрузить библиотеку глобуса');data=d;const params=new URLSearchParams(location.hash.slice(1));let saved=null;try{saved=JSON.parse(localStorage.getItem('chronos-state-v1'));}catch{}const raw=params.has('year')?Number(params.get('year')):saved?.year;if(Number.isInteger(raw)&&raw!==0&&raw>=MIN_YEAR&&raw<=MAX_YEAR)year=raw;const m=params.get('mode')||saved?.mode;if(['cultures','religions','relations'].includes(m))mode=m;const s=params.get('culture')||saved?.selected;if(data.cultures.some(c=>c.id===s))selected=s;if(!current().some(c=>c.id===selected))selected=chooseCurrent();
 globe=new Globe($('#globe'),l,id=>selectCulture(id,false));globe.onEmpty=()=>{setPanel(null,false);toggleYear(false);toggleLegend(false);};globe.onInteract=()=>{$('#autoRotate').setAttribute('aria-pressed','false');$('#autoRotate').setAttribute('aria-label','Включить плавное вращение');};$('#loading').hidden=true;
 const ticks=[-100000,-12000,-4000,-1000,1,1000,1800,2025];$('#ticks').innerHTML=ticks.map(y=>`<span style="left:${yearToPosition(y)/10}%">${y<0?'−':''}${Math.abs(y).toLocaleString('ru-RU')}</span>`).join('');bind();render();setPanel(null,false);
 }catch(err){$('#loading').innerHTML='Не удалось проявить карту. <button id="retryLoad">Попробовать ещё раз</button>';$('#loading').style.pointerEvents='auto';$('#retryLoad').onclick=()=>location.reload();console.error(err);toast(err.message);}}
init();
